from pulse.ingestion.models import Trend
from pulse.config import CATEGORIES, VC_STEPS, REGIONS

# ── Helper to build category/vc/region dicts from ordered lists ──────
CAT_KEYS = list(CATEGORIES)  # 13 categories in order
VC_KEYS = list(VC_STEPS)     # 8 VC steps in order
REG_KEYS = list(REGIONS)     # 4 regions in order

def cat(color, care, styling, body, fcn, fca, ffi, lad, hdw, adw, hsc, toi, ic):
    # 2.12.0 (O13): `toi` = Toilet Care, split out of Hard-Surface Cleaner.
    return dict(zip(CAT_KEYS, [color, care, styling, body, fcn, fca, ffi, lad, hdw, adw, hsc, toi, ic]))

def vc(raw, form, mfg, pkg, sc, mkt, comm, cons):
    return dict(zip(VC_KEYS, [raw, form, mfg, pkg, sc, mkt, comm, cons]))

def reg(eu, na, asia, hg):
    return dict(zip(REG_KEYS, [eu, na, asia, hg]))


def _ai_snapshot(t):
    """Immutable AI baseline snapshot of a trend's scoreable fields.

    Captured at seed time (June 2026 multi-expert proposals layer) so the
    "AI suggestion" reference shown alongside human proposals always reflects
    the originally-seeded values, even after admin edits or endorsements.
    2.11.0 (O7): includes the uncertainty score.
    """
    return {
        "probability": t.probability,
        "gp1_pct_affected": t.gp1_pct_affected,
        "peak_year": t.peak_year,
        "diffusion_curve": t.diffusion_curve,
        "uncertainty": getattr(t, "uncertainty", None),
        "category_exposure": dict(t.category_exposure or {}),
        "regional_exposure": dict(t.regional_exposure or {}),
        "vc_exposure": dict(t.vc_exposure or {}),
    }


